/** Odešle storno s platným CSRF tokenem (token se vezme z formuláře změny stavu na stránce). */
private function postCancel(Order $order): void
{
    $crawler = $this->client->request('GET', '/admin/legacy/order?id='.$order->id->value);
    $token = $crawler->filter('input[name="_csrf"]');
    $this->client->request('POST', '/admin/legacy/order_cancel?id='.$order->id->value, [
        'reason' => '',
        '_csrf' => $token->count() > 0 ? $token->attr('value') : $this->sessionToken(),
    ]);
}

private function sessionToken(): string
{
    $token = $this->client->getRequest()->getSession()->get('legacy_csrf_token');
    self::assertIsString($token);

    return $token;
}

